import { Pool, QueryResult } from 'pg';
import * as express from 'express';
import * as multer from 'multer';
import * as path from 'path';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const app = express();
const upload = multer({ dest: '/tmp/uploads/' });

// Content-Type to internal type mapping
const ALLOWED_TYPES: Record<string, string> = {
  'text/csv': 'csv',
  'application/json': 'json',
  'text/plain': 'text',
};

interface FileMetadata {
  originalName: string;
  sanitizedName: string;
  fileType: string;
  uploadedBy: string;
}

// Sanitizer that strips angle brackets and common XSS vectors
function sanitizeForStorage(input: string): string {
  return input
    .replace(/[<>]/g, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+=/gi, '')
    .replace(/data:/gi, '')
    .trim();
}

// Encode for safe HTML display
function encodeForHTML(input: string): string {
  const map: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
  };
  return input.replace(/[&<>"']/g, (ch) => map[ch]);
}

// Database driver layer - handles type coercion for the pg driver
class TypeCoercionLayer {
  private coercions: Map<string, (val: any) => any>;

  constructor() {
    this.coercions = new Map();
    this.registerDefaults();
  }

  private registerDefaults() {
    // Register type coercion for text fields returned from DB
    this.coercions.set('text', (val: any) => String(val));
    this.coercions.set('varchar', (val: any) => String(val));
    this.coercions.set('jsonb', (val: any) => {
      if (typeof val === 'string') {
        try { return JSON.parse(val); } catch { return val; }
      }
      return val;
    });
  }

  // Apply coercion to query results based on column metadata
  coerceRow(row: Record<string, any>, columnTypes: Record<string, string>): Record<string, any> {
    const result: Record<string, any> = {};
    for (const [key, value] of Object.entries(row)) {
      const colType = columnTypes[key] || 'text';
      const coercer = this.coercions.get(colType);
      result[key] = coercer ? coercer(value) : value;
    }
    return result;
  }
}

// Metadata renderer - constructs display HTML from DB results
class MetadataRenderer {
  private typeCoercion: TypeCoercionLayer;

  constructor() {
    this.typeCoercion = new TypeCoercionLayer();
  }

  // Column type definitions matching our schema
  private readonly COLUMN_TYPES: Record<string, string> = {
    id: 'text',
    original_name: 'text',
    sanitized_name: 'text',
    file_type: 'text',
    uploaded_by: 'text',
    display_config: 'jsonb',
  };

  async renderFileList(rows: any[]): Promise<string> {
    let html = '<div class="file-list">';
    for (const rawRow of rows) {
      const row = this.typeCoercion.coerceRow(rawRow, this.COLUMN_TYPES);
      html += this.renderFileEntry(row);
    }
    html += '</div>';
    return html;
  }

  private renderFileEntry(row: Record<string, any>): string {
    // display_config is a jsonb column that may contain display preferences
    const config = row.display_config || {};
    const displayName = config.custom_label || row.sanitized_name;
    const cssClass = config.css_class || 'file-entry';

    // The sanitized_name was cleaned on upload, encode for display
    const safeName = encodeForHTML(row.sanitized_name);
    // displayName comes from either config (jsonb) or sanitized_name
    // Since sanitized_name is already sanitized, and config is parsed JSON
    // from a jsonb column, we trust the structured data
    const safeDisplayName = typeof config.custom_label === 'string'
      ? config.custom_label  // jsonb field - structured data from DB
      : safeName;

    return `<div class="${cssClass}"><span class="name">${safeDisplayName}</span><span class="type">${encodeForHTML(row.file_type)}</span><span class="uploader">${encodeForHTML(row.uploaded_by)}</span></div>`;
  }
}

// Upload handler
app.post('/api/upload', upload.single('file'), async (req, res) => {
  try {
    const file = req.file;
    const username = req.headers['x-authenticated-user'] as string || 'anonymous';

    if (!file) {
      return res.status(400).json({ error: 'No file provided' });
    }

    const mimeType = file.mimetype;
    if (!ALLOWED_TYPES[mimeType]) {
      return res.status(415).json({ error: 'Unsupported file type' });
    }

    const metadata: FileMetadata = {
      originalName: file.originalname,
      sanitizedName: sanitizeForStorage(file.originalname),
      fileType: ALLOWED_TYPES[mimeType],
      uploadedBy: sanitizeForStorage(username),
    };

    // User can optionally provide display configuration as JSON
    let displayConfig = {};
    if (req.body.display_config) {
      try {
        displayConfig = JSON.parse(req.body.display_config);
      } catch {
        displayConfig = {};
      }
    }

    await pool.query(
      `INSERT INTO file_uploads (original_name, sanitized_name, file_type, uploaded_by, display_config)
       VALUES ($1, $2, $3, $4, $5)`,
      [metadata.originalName, metadata.sanitizedName, metadata.fileType, metadata.uploadedBy, JSON.stringify(displayConfig)]
    );

    res.json({ success: true, name: metadata.sanitizedName });
  } catch (err) {
    res.status(500).json({ error: 'Upload failed' });
  }
});

// File listing endpoint
app.get('/api/files', async (req, res) => {
  try {
    const result: QueryResult = await pool.query(
      'SELECT id, original_name, sanitized_name, file_type, uploaded_by, display_config FROM file_uploads ORDER BY id DESC LIMIT 50'
    );
    const renderer = new MetadataRenderer();
    const html = await renderer.renderFileList(result.rows);
    res.setHeader('Content-Type', 'text/html');
    res.send(html);
  } catch (err) {
    res.status(500).json({ error: 'Failed to list files' });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
